   938→        .stagger-children.in-view > *:nth-child(5) { animation: fadeSlideUp .4s .24s ease both; }
   939→        .stagger-children.in-view > *:nth-child(6) { animation: fadeSlideUp .4s .30s ease both; }
   940→        @keyframes fadeSlideUp {
   941→            from { opacity:0; transform:translateY(14px); }
