  4150→    // Remove oversized SVGs injected by extensions (width > 24px is suspicious in pagination)
  4151→    document.querySelectorAll('#paginationLinks svg, .pagination svg').forEach(s => {
  4152→        try {
  4153→            const w = parseFloat(s.getAttribute('width') || '0');
  4154→            const h = parseFloat(s.getAttribute('height') || '0');
  4155→            if ((w > 24 || h > 24) && !s.closest('.bi')) s.remove();
  4156→        } catch(e) {}
  4157→    });
  4158→}
  4159→document.addEventListener('DOMContentLoaded', function() {
  4160→    removeKnownChevrons();
  4161→    document.querySelectorAll('#paginationLinks, .pagination, nav.d-flex').forEach(el => {
