   201→    public function impersonate(Request $request, Branch $branch)
   202→    {
   203→        $user = auth()->user();
   204→        if (! $user) {
   205→            abort(403);
   206→        }
   207→        // defensive: prefer helper methods if available
   208→        $isOwner = false;
   209→        try {
   210→            if (method_exists($user, 'isOwner')) $isOwner = $user->isOwner();
   211→            elseif (method_exists($user, 'hasRole')) $isOwner = $user->hasRole('owner');
   212→        } catch (\Throwable $e) {
   213→            $isOwner = false;
   214→        }
   215→        if (! $isOwner) {
   216→            // include current roles to help debugging instead of immediate 403
   217→            try {
   218→                $roles = $user->getRoleNames()->toArray();
   219→            } catch (\Throwable $e) {
   220→                $roles = [];
   221→            }
   222→            \Log::warning('Impersonate denied: user lacks owner role', ['user_id' => $user->id, 'roles' => $roles]);
   223→            return back()->with('error', 'Akses ditolak: Anda tidak memiliki peran owner. Peran saat ini: ' . implode(',', $roles));
   224→        }
   225→
   226→        if (! $branch->admin_id) {
   227→            return back()->with('error', 'Cabang belum memiliki akun admin');
   228→        }
   229→
   230→        $admin = User::find($branch->admin_id);
   231→        if (! $admin) {
   232→            return back()->with('error', 'Akun admin cabang tidak ditemukan');
   233→        }
   234→
   235→        // store original user id to allow leaving impersonation
   236→        $request->session()->put('impersonate.original_user', $user->id);
   237→        $request->session()->put('impersonate.branch_id', $branch->id);
   238→
   239→        // log in as branch admin and regenerate session to avoid stale intended URL/session
   240→        Auth::loginUsingId($admin->id);
   241→        try {
   242→            $request->session()->regenerate();
   243→            // clear any intended owner URL so user doesn't get redirected back to owner pages
   244→            $intended = $request->session()->get('url.intended');
   245→            if ($intended && str_starts_with($intended, url('/').'/owner')) {
   246→                $request->session()->forget('url.intended');
   247→            }
   248→        } catch (\Throwable $e) {
   249→            // ignore session regen failures
   250→        }
   251→
   252→        return redirect()->route('dashboard');
   253→    }
